function buildRaw(to, subject, html) {
  const mime = [
    'From: Hector Meza <h.mezarealty@gmail.com>',
    `To: ${to}`,
    'Reply-To: hmeza@briggsfreeman.com',
    `Subject: ${subject}`,
    'MIME-Version: 1.0',
    'Content-Type: text/html; charset=UTF-8',
    '',
    html
  ].join('\r\n');
  return Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
const link = 'https://g.page/r/CabJGOEHci6qEBM/review';
const v = ($input.first().json.values) || [];
const now = Date.now();
const DAY = 86400000;

function shell(inner, first) {
  return [
    `<div style="font-family:'Aptos','Segoe UI',Calibri,Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#222;max-width:560px;">`,
    `<p style="margin:0 0 16px;">Hi ${first},</p>`,
    inner,
    `<p style="margin:0 0 20px;"><a href="${link}" style="display:inline-block;background:#1a3c34;color:#ffffff;padding:12px 24px;border-radius:6px;text-decoration:none;font-weight:bold;">Leave a review</a></p>`,
    `<p style="margin:24px 0 0;">With gratitude,<br><strong>Hector Meza</strong><br>Briggs Freeman Sotheby's International Realty<br>(214) 686-5641 &middot; <a href="https://hectormeza.com" style="color:#1a3c34;">hectormeza.com</a></p>`,
    `</div>`
  ].join('');
}

const out = [];
v.forEach((r, i) => {
  const row = i + 2;
  const g = k => ((r[k] === undefined || r[k] === null) ? '' : String(r[k])).trim();
  const first = g(0), email = g(1), sent = g(5), n1 = g(6), n2 = g(7), reviewed = g(8);
  if (!first || !email || !sent || reviewed) return;
  if (!n1 && now - Date.parse(sent) >= 2 * DAY) {
    const inner = `<p style="margin:0 0 16px;">I hope you're settling in well. Just a quick reminder about the Google review, in case life got in the way. It usually does. It takes about two minutes and it genuinely helps.</p>`;
    out.push({ json: { row, col: 'G', ts: new Date().toISOString(), email,
      subject: `Quick reminder, ${first}`, html: shell(inner, first), raw: buildRaw(email, `Quick reminder, ${first}`, shell(inner, first)) }});
  } else if (n1 && !n2 && now - Date.parse(n1) >= 3 * DAY) {
    const inner = `<p style="margin:0 0 16px;">I promise this is my last note about it. If you can spare two minutes for a quick Google review, it would mean a lot. And if it is not your thing, no worries at all. It was a pleasure either way.</p>`;
    out.push({ json: { row, col: 'H', ts: new Date().toISOString(), email,
      subject: `Last note from me, ${first}`, html: shell(inner, first), raw: buildRaw(email, `Last note from me, ${first}`, shell(inner, first)) }});
  }
});
return out;

